-- TOC entry 515 (class 1255 OID 165514)
-- Name: aw_snapshot_all_user_stats(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aw_snapshot_all_user_stats(p_snapshot_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user record;
  v_count integer := 0;
begin
  for v_user in
    select u.id
    from auth.users u
  loop
    perform public.aw_snapshot_user_stats(v_user.id, p_snapshot_date);
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


