--

CREATE FUNCTION public.get_staff_role(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (
      select up.role
      from public.user_profiles up
      where up.user_id = p_user_id
      limit 1
    ),
    'user'
  )::text;
$$;


